void tach_cmd_lut_ena (void)
{	
  static const Cmd_Array1 cmd_array[] = 
    {
      {INPUT_RS_IGNITION   | INPUT_ON , tach_rs_ign_on  },
      {INPUT_RS_IGNITION              , tach_rs_ign_off },
      {INPUT_IGNITION	   | INPUT_ON , tach_ign_on     }, 
      {INPUT_IGNITION                 , tach_ign_off    }, 
    };	
    
	
    core_contract_db3_tach_pwm_select();
	
    CMD_LUT_INSERT1(cmd_array,EXEC_MODE_NORMAL);

}



